    func testLivePlaybackRecoveryTriesBackupLineBeforeNextChannel() throws {
        let primary = try XCTUnwrap(
            URL(string: "https://example.com/cctv1-primary.m3u8")
        )
        let backup = try XCTUnwrap(
            URL(string: "https://example.com/cctv1-backup.m3u8")
        )
        let current = LiveChannel(
            groupName: "央视频道",
            name: "CCTV-1",
            streams: [
                LiveStream(name: "主线", url: primary),
                LiveStream(name: "备线", url: backup)
            ]
        )
        let next = try makeLiveChannel(
            name: "CCTV-2",
            streamPath: "cctv2"
        )

        let catalog = AcceptedImportedCatalog(sourceID: UUID(), playlist: LivePlaylist(
            format: .m3u, groups: [LiveGroup(name: "G", channels: [current, next])]
        ))
        let candidates = LivePlaybackRecoveryPolicy.importedCandidates(
            catalog: catalog, channels: [current, next],
            starting: catalog.selections(for: current)[0], excluding: []
        )

        XCTAssertEqual(
            candidates.map { "\($0.channel.name)::\($0.stream.name)" },
            ["CCTV-1::主线", "CCTV-1::备线", "CCTV-2::默认"]
        )
    }

    func testLivePlaybackRecoveryExcludesAttemptedAndDuplicateURLs() throws {
        let sharedURL = try XCTUnwrap(
            URL(string: "https://example.com/shared.m3u8")
        )
        let current = LiveChannel(
            groupName: "央视频道",
            name: "CCTV-1",
            streams: [LiveStream(name: "主线", url: sharedURL)]
        )
        let duplicate = LiveChannel(
            groupName: "央视频道",
            name: "CCTV-2",
            streams: [LiveStream(name: "重复", url: sharedURL)]
        )
        let catalog = AcceptedImportedCatalog(sourceID: UUID(), playlist: LivePlaylist(
            format: .m3u, groups: [LiveGroup(name: "G", channels: [current, duplicate])]
        ))
        let attempted = try XCTUnwrap(ImportedRouteTransport(current.streams[0]))
        let candidates = LivePlaybackRecoveryPolicy.importedCandidates(
            catalog: catalog, channels: [current, duplicate],
            starting: catalog.selections(for: current)[0], excluding: [attempted]
        )

        XCTAssertTrue(candidates.isEmpty)
    }

    func testXtreamLiveRecoveryStaysWithinCurrentChannel() throws {
        let current = LiveChannel(
            groupName: "News",
            name: "Current",
            streams: [
                LiveStream(
                    name: "HLS",
                    url: try XCTUnwrap(URL(string: "https://example.com/current.m3u8"))
                ),
                LiveStream(
                    name: "TS",
                    url: try XCTUnwrap(URL(string: "https://example.com/current.ts"))
                )
            ]
        )
        let unrelated = try makeLiveChannel(
            name: "Unrelated",
            streamPath: "unrelated"
        )

        let candidates = LivePlaybackRecoveryPolicy.candidates(
            channels: [current, unrelated],
            startingChannel: current,
            startingStream: current.streams[0],
            scope: .currentChannel
        )

        XCTAssertEqual(
            candidates.map { $0.channel.name },
            ["Current", "Current"]
        )
        XCTAssertEqual(
            candidates.map { $0.stream.name },
            ["HLS", "TS"]
        )
    }

    func testXtreamLiveFailurePolicyStopsOnAccountErrorsOnly() {
        XCTAssertFalse(
