            PlayerActivityOverlayPolicy.isActive(
                snapshot: PlayerSnapshot(
                    status: .playing,
                    isSeeking: true,
                    seekTarget: 2_188
                )
            )
        )
        XCTAssertTrue(
            PlayerActivityOverlayPolicy.isActive(
                snapshot: PlayerSnapshot(
                    status: .paused,
                    isPausedForCache: true
                )
            )
        )
        XCTAssertTrue(
