    func testPlaybackEndArbiterClassifiesFinalEndFileOnce() {
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 99,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .natural
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 0,
                duration: 0,
                isProtectedByUserSeek: false
            ),
            .natural
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 2,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 100,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .stopped
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: true,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 100,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .ignored
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 100,
                duration: 100,
                isProtectedByUserSeek: true,
                isUserSeekToBoundary: true
            ),
            .userSeekBoundary
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: true,
                position: 40,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .premature
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: false,
                isPausedForCache: false,
                position: 100,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .premature
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 0,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 40,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .premature
        )
        XCTAssertEqual(
            MPVPlaybackEndPolicy.disposition(
                endFileReason: 4,
                error: -13,
                isReplacingMedia: false,
                hasStartedPlayback: true,
                isPausedForCache: false,
                position: 40,
                duration: 100,
                isProtectedByUserSeek: false
            ),
            .failed
        )
    }

