    func testAndroidADBTransportExitsImmediatelyAndClassifiesDeadline() {
        let policy = AndroidADBTransportPolicy.production
        XCTAssertEqual(
            policy.action(
                elapsed: 30,
                targetState: .offline,
                processPresent: false,
                processOwned: false,
                reconnectAttempted: true,
                gpuBackend: .host
            ),
            .fail(.emulatorExitedBeforeADB)
        )
        XCTAssertEqual(
            policy.action(
                elapsed: 180,
                targetState: .offline,
                processPresent: true,
                processOwned: true,
                reconnectAttempted: true,
                reconnectFailed: true,
                gpuBackend: .host
            ),
            .fail(.adbReconnectFailed)
        )
        XCTAssertEqual(
            policy.action(
                elapsed: 180,
                targetState: .offline,
                processPresent: true,
                processOwned: true,
                reconnectAttempted: true,
                gpuBackend: .host
            ),
            .fail(.hostGPUADBOfflineTimeout)
        )
        XCTAssertEqual(
            policy.action(
                elapsed: 180,
                targetState: .offline,
                processPresent: true,
                processOwned: true,
                reconnectAttempted: true,
                gpuBackend: .software
            ),
            .fail(.softwareGPUADBOfflineTimeout)
        )
        XCTAssertEqual(
            policy.action(
                elapsed: 180,
                targetState: .missing,
                processPresent: true,
                processOwned: true,
                reconnectAttempted: false,
                gpuBackend: .host
            ),
            .fail(.adbSerialMissingTimeout)
        )
    }

    func testAndroidADBReconnectDiagnosticSurvivesIndependentEncoding()
        throws {
