    func testAndroidLifecycle15TwoRuntimeInstancesShareOneAdmission()
        async throws {
        let processWideAdmission = AndroidRuntimeStartupSingleFlight()
        let launchGate = NodeReadinessTestGate()
        let launcher = AndroidEmulatorLauncherMock()
        let readyCallers = NodeReadinessTestCounter()
        let firstRuntimeCallers = (0..<5).map { _ in
            Task {
                await readyCallers.increment()
                try await processWideAdmission.ensureRuntime {
                    await launcher.launch(waitingOn: launchGate)
                }
            }
        }
        let secondRuntimeCallers = (0..<5).map { _ in
            Task {
                await readyCallers.increment()
                try await processWideAdmission.ensureRuntime {
                    await launcher.launch(waitingOn: launchGate)
                }
            }
        }
        for _ in 0..<20_000 {
            if await readyCallers.value == 10 { break }
            await Task.yield()
        }
        var sawLaunch = false
        for _ in 0..<20_000 {
            if await launcher.launchInvocationCount == 1 {
                sawLaunch = true
                break
            }
            await Task.yield()
        }
        XCTAssertTrue(sawLaunch)
        // Every caller has been scheduled, but returning from the counter
        // actor and entering the admission actor are separate suspension
        // points. Give all ten a chance to join before releasing the shared
        // launch operation; otherwise the test can manufacture a late caller
        // after the first flight has legitimately completed.
        for _ in 0..<1_000 { await Task.yield() }
        var launchCount = await launcher.launchInvocationCount
        XCTAssertEqual(launchCount, 1)
        await launchGate.open()
        for caller in firstRuntimeCallers + secondRuntimeCallers {
            try await caller.value
        }
        launchCount = await launcher.launchInvocationCount
        XCTAssertLessThanOrEqual(launchCount, 1)
    }

    func testPrivateAVDOwnershipNormalizesAliasesAndRejectsOutsideFiles() throws {
        let root = URL(fileURLWithPath: "/tmp", isDirectory: true)
            .appendingPathComponent("AVDOwnership-\(UUID().uuidString)")
        let avd = root.appendingPathComponent("private.avd")
        try FileManager.default.createDirectory(at: avd, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }
        // lsof reports opened files; Foundation resolves aliases of existing paths.
        try Data().write(to: avd.appendingPathComponent("userdata.img"))
        let alias = root.appendingPathComponent("alias.avd")
        try FileManager.default.createSymbolicLink(at: alias, withDestinationURL: avd)
        let matches = AndroidDexBridgeRuntime.privateAVDFilePathMatches
        XCTAssertTrue(matches(alias.appendingPathComponent("userdata.img").path, avd))
        XCTAssertTrue(matches(avd.appendingPathComponent("userdata.img").path, alias))
        XCTAssertTrue(matches("/private" + avd.appendingPathComponent("userdata.img").path, avd))
        XCTAssertFalse(matches(avd.path + "-other/userdata.img", avd))
        XCTAssertFalse(matches(root.appendingPathComponent("foreign.avd/userdata.img").path, avd))
        XCTAssertFalse(matches(avd.path + "/../foreign.avd/userdata.img", avd))
        XCTAssertFalse(matches("relative/userdata.img", avd))
    }

    func testAndroidRealLifecycleStartAdoptAndStop() async throws {
        guard ProcessInfo.processInfo.environment[
            "OKVIDEOMAC_RUN_ANDROID_INTEGRATION"
        ] == "1" || UserDefaults.standard.bool(
            forKey: "OKVideoMac.RunAndroidIntegration"
        ) else {
            throw XCTSkip("requires explicit real private-AVD integration run")
        }
        let support = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/OKVideoMac",
                isDirectory: true
            )
        let sdk = try androidIntegrationSDKRoot()
        let firstRuntime = AndroidDexBridgeRuntime(
            applicationSupportDirectory: support
        )
        await firstRuntime.setUserSelectedSDKRoot(sdk)
        do {
            let callers = (0..<10).map { _ in
                Task { try await firstRuntime.start() }
            }
            for caller in callers {
                try await caller.value
            }
            let first = await firstRuntime.diagnosticSnapshot()
            let firstPID = try XCTUnwrap(first.emulatorPID)
            XCTAssertTrue(first.emulatorProcessRunning)
            XCTAssertEqual(first.launchOrigin, .currentLaunch)
            XCTAssertEqual(
                first.timeline.filter {
                    $0.event == "emulator_process_launched"
                }.count,
                1
            )
            XCTAssertEqual(
                first.emulatorArguments,
                AndroidDexBridgeRuntime.emulatorLaunchArguments(
                    consolePort: first.emulatorConsolePort ?? 0
                )
            )

            // Simulates a new App/runtime object after a crash left the
            // private Emulator alive. It must adopt the same PID, not launch.
            let restartedRuntime = AndroidDexBridgeRuntime(
                applicationSupportDirectory: support
            )
            await restartedRuntime.setUserSelectedSDKRoot(sdk)
            try await restartedRuntime.start()
            let adopted = await restartedRuntime.diagnosticSnapshot()
            XCTAssertEqual(adopted.emulatorPID, firstPID)
            XCTAssertEqual(adopted.launchOrigin, .adoptedExisting)
            XCTAssertEqual(
                adopted.ownershipClassification,
                .ownedExistingHealthy
            )

            await restartedRuntime.stop()
            let stopped = await restartedRuntime.diagnosticSnapshot()
            let shutdownEvidence = (stopped.lifecycleConflictReason ?? "none")
                + " | " + stopped.recentCommands.suffix(8).map {
                    "\($0.category): exit=\($0.exitCode), timeout=\($0.timedOut), duration=\($0.duration)"
                }.joined(separator: "; ")
            XCTAssertFalse(stopped.emulatorProcessRunning, shutdownEvidence)
            XCTAssertEqual(stopped.shutdownMechanism, .adbEmuKill)
            XCTAssertNotNil(stopped.shutdownCompletedAt)
            XCTAssertFalse(stopped.shutdownForced)
            let managedAVD = support
                .appendingPathComponent("AndroidRuntime/avd")
                .appendingPathComponent("OKVideoMac_Runtime.avd")
            let remainingLocks = try FileManager.default
                .contentsOfDirectory(atPath: managedAVD.path)
                .filter { $0.lowercased().contains("lock") }
            XCTAssertTrue(remainingLocks.isEmpty)
        } catch {
            await firstRuntime.stop()
            throw error
        }
    }

    func testAndroidRealExternalModeCoordinatorBridgeDexAndSecondStart()
        async throws {
        guard ProcessInfo.processInfo.environment[
            "OKVIDEOMAC_RUN_ANDROID_EXTERNAL_MODE_E2E"
        ] == "1" || UserDefaults.standard.bool(
            forKey: "OKVideoMac.RunAndroidExternalModeE2E"
        ) else {
            throw XCTSkip("requires explicit real External mode E2E run")
        }

        let fileManager = FileManager.default
        let support = fileManager.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/OKVideoMac",
                isDirectory: true
            )
        let sdk = try androidIntegrationSDKRoot()
        let fixtureJAR = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent(
                "Vendor/Build/AndroidRuntimeMatrix/matrix-fixture.jar"
            )
        guard fileManager.fileExists(atPath: fixtureJAR.path) else {
            throw XCTSkip("deterministic Dex matrix fixture is not built")
        }

        let selectionSupport = fileManager.temporaryDirectory
            .appendingPathComponent(
                "AndroidExternalModeE2E-\(UUID().uuidString)",
                isDirectory: true
            )
        try fileManager.createDirectory(
            at: selectionSupport,
            withIntermediateDirectories: true
        )
        let defaultsSuite = "AndroidExternalModeE2E.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsSuite))
        defaults.set(
            sdk.path,
            forKey: AndroidRuntimeModeStore.legacySDKRootDefaultsKey
        )
        defer {
            defaults.removePersistentDomain(forName: defaultsSuite)
            try? fileManager.removeItem(at: selectionSupport)
        }

        let serverPort = 28_979
        let server = Process()
        server.executableURL = URL(fileURLWithPath: "/usr/bin/python3")
        server.arguments = [
            "-m", "http.server", "\(serverPort)",
            "--bind", "127.0.0.1",
            "--directory", fixtureJAR.deletingLastPathComponent().path
        ]
        server.standardOutput = FileHandle.nullDevice
        server.standardError = FileHandle.nullDevice
        try server.run()
        defer {
            if server.isRunning { server.terminate() }
        }
        let fixtureURL = URL(
            string: "http://127.0.0.1:\(serverPort)/"
                + fixtureJAR.lastPathComponent
        )!
        var serverReady = false
        for _ in 0..<50 {
            if !server.isRunning { break }
            if let (_, response) = try? await URLSession.shared.data(
                from: fixtureURL
            ), (response as? HTTPURLResponse)?.statusCode == 200 {
                serverReady = true
                break
            }
            try await Task.sleep(nanoseconds: 100_000_000)
        }
        XCTAssertTrue(serverReady, "fixture HTTP server did not start")

        let runtime = AndroidDexBridgeRuntime(
            applicationSupportDirectory: support
        )
        let routingProbe = AndroidRuntimeRoutingProbe()
        let coordinator = try AndroidRuntimeModeCoordinator(
            store: AndroidRuntimeModeStore(
                applicationSupportDirectory: selectionSupport,
                defaults: defaults
            ),
            layout: AndroidRuntimeLayout(
                applicationSupportDirectory: support
            ),
            catalog: try BundledRuntimeCatalog.load(),
            externalValidator: ExternalAndroidRuntimeValidator(
                applicationSupportDirectory: support
            ),
            managedRuntimeUsableAtMigration: false,
            managedUsability: { false },
            ensureManagedReady: {
                await routingProbe.recordManagedAdmission()
            },
            cancelManagedAdmission: {},
            configureSession: { mode, root in
                await routingProbe.recordConfiguration(
                    mode: mode,
                    sdkRoot: root
                )
                await runtime.setRuntimeSelection(
                    mode: mode,
                    externalSDKRoot: root
                )
            },
            sessionStatus: { await runtime.status() }
        )
        let client = AndroidDexBridgeClient(
            runtime: runtime,
            runtimePrerequisite: {
                try await coordinator.prepareRuntime()
            }
        )

        func runADB(
            port: Int,
            serial: String,
            arguments: [String]
        ) throws -> String {
            let process = Process()
            let output = Pipe()
            process.executableURL = sdk.appendingPathComponent(
                "platform-tools/adb"
            )
            process.arguments = [
                "-P", "\(port)", "-s", serial
            ] + arguments
            process.standardOutput = output
            process.standardError = output
            try process.run()
            let data = output.fileHandleForReading.readDataToEndOfFile()
            process.waitUntilExit()
            let text = String(decoding: data, as: UTF8.self)
            XCTAssertEqual(process.terminationStatus, 0, text)
            return text
        }

        do {
            let migrated = await coordinator.refresh()
            XCTAssertEqual(migrated.mode, .external)
            XCTAssertEqual(migrated.selectionSource, .legacyExternalMigration)
            XCTAssertTrue(
                migrated.externalValidation?.launchCapability.available == true
            )

            try await coordinator.prepareRuntime()
            _ = try await client.startRuntime()
            let first = await client.diagnosticSnapshot()
            XCTAssertEqual(first.runtimeMode, .external)
            XCTAssertEqual(first.sdkDiscoverySource, "explicit-external")
            XCTAssertEqual(first.adbDeviceState, "device")
            XCTAssertEqual(first.androidBootCompleted, true)
            XCTAssertEqual(first.bridgeProcessRunning, true)
            let adbPort = try XCTUnwrap(first.adbPrivateServer?.port)
            let serial = try XCTUnwrap(first.emulatorSerial)
            _ = try runADB(
                port: adbPort,
                serial: serial,
                arguments: [
                    "reverse", "tcp:\(serverPort)", "tcp:\(serverPort)"
                ]
            )

            let value = try await client.invoke(
                site: SiteConfiguration(
                    key: "runtime-external-e2e",
                    name: "Runtime External E2E",
                    type: 3,
                    api: "csp_MatrixFixture"
                ),
                configurationID: "runtime-external-e2e",
                configurationHosts: [],
                jarReference: fixtureURL.absoluteString,
                baseURL: nil,
                method: "home",
                arguments: [.bool(true)]
            )
            guard case .object(let object) = value,
                  case .array(let list)? = object["list"],
                  case .object(let item)? = list.first else {
                XCTFail("unexpected deterministic Dex response: \(value)")
                _ = await client.stopRuntime()
                return
            }
            XCTAssertEqual(
                item["vod_name"],
                .string("OKVideoMac Matrix PASS")
            )

            _ = await client.stopRuntime()
            let stopped = await client.diagnosticSnapshot()
            XCTAssertFalse(stopped.emulatorProcessRunning)
            XCTAssertFalse(stopped.shutdownForced)

            try await coordinator.prepareRuntime()
            _ = try await client.startRuntime()
            let second = await client.diagnosticSnapshot()
            XCTAssertEqual(second.runtimeMode, .external)
            XCTAssertEqual(second.adbDeviceState, "device")
            XCTAssertEqual(second.androidBootCompleted, true)
            XCTAssertEqual(second.bridgeProcessRunning, true)
            let emulatorPID = try XCTUnwrap(second.emulatorPID)
            let privateADBServerPID = try XCTUnwrap(
                second.adbPrivateServer?.pid
            )
            let terminationStartedAt = ProcessInfo.processInfo.systemUptime
            let terminationOutcome = await client
                .shutdownForApplicationTermination()
            let terminationElapsed = ProcessInfo.processInfo.systemUptime
                - terminationStartedAt
            print(String(
                format: "ANDROID_APP_TERMINATION_ELAPSED=%.3f",
                terminationElapsed
            ))
            XCTAssertEqual(terminationOutcome.mechanism, .adbEmuKill)
            XCTAssertFalse(terminationOutcome.forced)
            XCTAssertNotNil(terminationOutcome.completedAt)
            let terminationFallbackTimeout = await MainActor.run {
                OKVideoMacAppDelegate.terminationFallbackTimeout
            }
            XCTAssertLessThan(
                terminationElapsed,
                terminationFallbackTimeout
            )
            XCTAssertEqual(Darwin.kill(emulatorPID, 0), -1)
            XCTAssertEqual(Darwin.kill(privateADBServerPID, 0), -1)

            let managedAdmissionCount = await routingProbe
                .managedAdmissionCount
            XCTAssertEqual(managedAdmissionCount, 0)
            let configurations = await routingProbe.configurations
            XCTAssertFalse(configurations.isEmpty)
            XCTAssertTrue(configurations.allSatisfy {
                $0.mode == .external
                    && $0.sdkRoot == sdk.standardizedFileURL
                        .resolvingSymlinksInPath()
            })
        } catch {
            _ = await client.stopRuntime()
            throw error
        }
    }

    func testAndroidRealLifecycleQuitDuringStartupDoesNotOrphan()
        async throws {
        guard ProcessInfo.processInfo.environment[
            "OKVIDEOMAC_RUN_ANDROID_STARTUP_CANCEL_INTEGRATION"
        ] == "1" || UserDefaults.standard.bool(
            forKey: "OKVideoMac.RunAndroidStartupCancelIntegration"
        ) else {
            throw XCTSkip("requires explicit startup-cancellation integration run")
        }
        let support = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/OKVideoMac",
                isDirectory: true
            )
        let runtime = AndroidDexBridgeRuntime(
            applicationSupportDirectory: support
        )
        await runtime.setUserSelectedSDKRoot(try androidIntegrationSDKRoot())
        let startup = Task { try await runtime.start() }
        var observedPID: Int32?
        for _ in 0..<240 {
            let snapshot = await runtime.diagnosticSnapshot()
            observedPID = snapshot.emulatorPID
            if observedPID != nil { break }
            try await Task.sleep(nanoseconds: 250_000_000)
        }
        XCTAssertNotNil(observedPID)
        await runtime.stop()
        _ = await startup.result
        let final = await runtime.diagnosticSnapshot()
        XCTAssertFalse(final.emulatorProcessRunning)
        XCTAssertNotEqual(
            final.shutdownMechanism,
            .refusedOwnershipMismatch
        )
        XCTAssertNotNil(final.shutdownCompletedAt)
        let managedAVD = support
            .appendingPathComponent("AndroidRuntime/avd")
            .appendingPathComponent("OKVideoMac_Runtime.avd")
        let remainingLocks = try FileManager.default
            .contentsOfDirectory(atPath: managedAVD.path)
            .filter { $0.lowercased().contains("lock") }
        XCTAssertTrue(remainingLocks.isEmpty)
    }

    func testAndroidRealApplicationTerminationIsBoundedAndClean()
        async throws {
        guard ProcessInfo.processInfo.environment[
            "OKVIDEOMAC_RUN_ANDROID_EXIT_INTEGRATION"
        ] == "1" || UserDefaults.standard.bool(
            forKey: "OKVideoMac.RunAndroidExitIntegration"
        ) else {
            throw XCTSkip("requires explicit real app-exit integration run")
        }

        let support = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/OKVideoMac",
                isDirectory: true
            )
        let runtime = AndroidDexBridgeRuntime(
            applicationSupportDirectory: support
        )
        await runtime.setUserSelectedSDKRoot(try androidIntegrationSDKRoot())
        do {
            try await runtime.start()
            let running = await runtime.diagnosticSnapshot()
            XCTAssertTrue(running.emulatorProcessRunning)
            XCTAssertEqual(running.adbDeviceState, "device")
            XCTAssertEqual(running.androidBootCompleted, true)
            let emulatorPID = try XCTUnwrap(running.emulatorPID)
            let privateADBServerPID = try XCTUnwrap(
                running.adbPrivateServer?.pid
            )

            let startedAt = ProcessInfo.processInfo.systemUptime
            let outcome = await runtime.shutdownForApplicationTermination()
            let elapsed = ProcessInfo.processInfo.systemUptime - startedAt
            print(String(
                format: "ANDROID_APP_TERMINATION_ELAPSED=%.3f",
                elapsed
            ))

            XCTAssertEqual(outcome.mechanism, .adbEmuKill)
            XCTAssertFalse(outcome.forced)
            XCTAssertNotNil(outcome.completedAt)
            let terminationFallbackTimeout = await MainActor.run {
                OKVideoMacAppDelegate.terminationFallbackTimeout
            }
            XCTAssertLessThan(
                elapsed,
                terminationFallbackTimeout
            )
            XCTAssertEqual(
                Darwin.kill(emulatorPID, 0),
                -1,
                "Emulator must exit before shutdown completes"
            )
            XCTAssertEqual(
                Darwin.kill(privateADBServerPID, 0),
                -1,
                "private ADB server must exit before shutdown completes"
            )
        } catch {
            await runtime.shutdownForApplicationTermination()
            throw error
        }
    }

    func testAndroidEmulatorDiagnosticLogTailIsBoundedAndRedacted() {
