            AndroidDexBridgeRuntime.installPreservesPackageContinuity(
                before: before,
                after: AndroidInstalledPackageContinuity(
                    firstInstallTime: after.firstInstallTime,
                    userID: after.userID + 1,
                    dataDirectory: after.dataDirectory
                )
            )
        )
    }

