    @MainActor
    func testPlayerWindowPreferenceStoreSeparatesAutomaticAndFixedSizes() throws {
        let suiteName = "OKVideoMacTests.PlayerWindow.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suiteName))
        defer { defaults.removePersistentDomain(forName: suiteName) }
        let key = "fixture.player-window"
        let store = PlayerWindowPreferenceStore(
            defaults: defaults,
            storageKey: key
        )

        store.saveUserFrame(
            contentSize: NSSize(width: 1_300, height: 540),
            windowFrame: NSRect(x: 100, y: 120, width: 1_300, height: 540),
            visibleFrame: NSRect(x: 0, y: 0, width: 2_000, height: 1_200),
            screenIdentifier: 42
        )
        XCTAssertEqual(store.preference.viewingWidth, 1_300)
        XCTAssertEqual(store.preference.fixedWidth, 1_152)
        XCTAssertEqual(store.preference.fixedHeight, 648)

        store.setMode(.fixedFrame)
        store.captureModeTransition(
            to: .fixedFrame,
            currentContentSize: NSSize(width: 1_300, height: 540)
        )
        store.saveUserFrame(
            contentSize: NSSize(width: 980, height: 720),
            windowFrame: NSRect(x: 180, y: 160, width: 980, height: 720),
            visibleFrame: NSRect(x: 0, y: 0, width: 2_000, height: 1_200),
            screenIdentifier: 42
        )

        let restored = PlayerWindowPreferenceStore(
            defaults: defaults,
            storageKey: key
        )
        XCTAssertEqual(restored.preference.mode, .fixedFrame)
        XCTAssertEqual(restored.preference.viewingWidth, 1_300)
        XCTAssertEqual(restored.preference.fixedWidth, 980)
        XCTAssertEqual(restored.preference.fixedHeight, 720)
        XCTAssertEqual(restored.preference.screenIdentifier, 42)
    }

    @MainActor
    func testPlayerWindowStagedMoveIsImmediateInMemoryAndDurableAfterFlush() throws {
        let suiteName = "OKVideoMacTests.PlayerWindowStage.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suiteName))
        defer { defaults.removePersistentDomain(forName: suiteName) }
        let key = "fixture.player-window-stage"
        let store = PlayerWindowPreferenceStore(defaults: defaults, storageKey: key)
        let visible = NSRect(x: 0, y: 0, width: 2_000, height: 1_200)
        store.saveUserFrame(
            contentSize: NSSize(width: 1_000, height: 600),
            windowFrame: NSRect(x: 100, y: 100, width: 1_000, height: 600),
            visibleFrame: visible,
            screenIdentifier: 7
        )
        let originalCenter = store.preference.normalizedCenterX

        store.stageUserFrame(
            contentSize: NSSize(width: 1_000, height: 600),
            windowFrame: NSRect(x: 700, y: 300, width: 1_000, height: 600),
            visibleFrame: visible,
            screenIdentifier: 7
        )
        XCTAssertNotEqual(store.preference.normalizedCenterX, originalCenter)
        XCTAssertEqual(
            PlayerWindowPreferenceStore(defaults: defaults, storageKey: key)
                .preference.normalizedCenterX,
            originalCenter
        )

        store.flushPendingUserFrame()
        let restored = PlayerWindowPreferenceStore(defaults: defaults, storageKey: key)
        XCTAssertEqual(restored.preference.normalizedCenterX, store.preference.normalizedCenterX)
        XCTAssertEqual(restored.preference.normalizedCenterY, store.preference.normalizedCenterY)
        XCTAssertEqual(restored.preference.screenIdentifier, 7)
    }

