        )
        XCTAssertFalse(
            CatPawHistoryMigrationPolicy.shouldCaptureRecoveredIdentity(
                isHistory: true,
                isAuthorizationRetry: false,
                isNodeProvider: true,
                hasAcceptedProviderReference: true,
                detailID: recoveredID
            )
        )
