        XCTAssertTrue(log.contains("NODE_RUNTIME_STARTUP_JOINED"))
        XCTAssertTrue(log.contains("NODE_RUNTIME_READY"))
        await service.stop()
    }

    func testCatPawPlaybackLeaseDefersOrdinaryRuntimeStopUntilRelease()
        async throws {
