            URL(string: ownedObject["url"] as? String ?? "")
        )
        XCTAssertEqual(normalizedURL.host, "127.0.0.1")
        XCTAssertEqual(normalizedURL.port, port)
        XCTAssertEqual(normalizedURL.path, "/website")

