    func recordStarted(_ requestID: UUID) {
        events.append("start:\(requestID)")
    }

    func recordAcknowledged(_ requestID: UUID) {
        events.append("ack:\(requestID)")
    }
}

private actor PlayerLifecycleTransitionTestGate {
    private var isSuspended = false
    private var continuation: CheckedContinuation<Void, Never>?

    func suspend() async {
        isSuspended = true
        await withCheckedContinuation { continuation in
            self.continuation = continuation
        }
    }

    func waitUntilSuspended() async throws {
        let deadline = Date().addingTimeInterval(5)
        while !isSuspended {
            guard Date() < deadline else {
                throw AppError.playback(
                    "Timed out waiting for lifecycle test suspension"
                )
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
    }

    func release() {
        continuation?.resume()
        continuation = nil
        isSuspended = false
    }
}

private actor NodeReadinessTestGate {
    private var isOpen = false
    private var waiters: [CheckedContinuation<Void, Never>] = []

    func wait() async {
        guard !isOpen else { return }
        await withCheckedContinuation { continuation in
            waiters.append(continuation)
        }
    }

    func open() {
        isOpen = true
        let pending = waiters
        waiters.removeAll()
        for waiter in pending {
            waiter.resume()
        }
    }
}

private actor NodeReadinessTestCounter {
    private(set) var value = 0

    func increment() {
        value += 1
    }
}

private actor AndroidEmulatorLauncherMock {
