private func makeQuarkEpisodeReference(
    stoken: String,
    passcode: String = ""
) throws -> String {
    let tokenData = try JSONSerialization.data(
        withJSONObject: [
            "shareId": "share-123",
            "fid": "file-456",
            "stoken": stoken,
            "passcode": passcode
        ],
        options: [.sortedKeys, .withoutEscapingSlashes]
    )
    let token = try XCTUnwrap(String(data: tokenData, encoding: .utf8))
    let outerData = try JSONSerialization.data(
        withJSONObject: [
            "providerId": "quark",
            "shareId": "share-123",
            "fileId": "file-456",
            "playToken": token
        ],
        options: [.sortedKeys, .withoutEscapingSlashes]
    )
    return outerData.base64EncodedString()
}

private func nodeEpisodeID(from request: HTTPRequest) throws -> String {
    let body = try XCTUnwrap(request.body)
    let value = try JSONDecoder().decode(JSONValue.self, from: body)
    return try XCTUnwrap(value.objectValue?["id"]?.stringValue)
}

private func quarkTokenRequestPasscode(
    from request: HTTPRequest
) throws -> String {
    let body = try XCTUnwrap(request.body)
    let object = try XCTUnwrap(
        JSONSerialization.jsonObject(with: body) as? [String: Any]
    )
    return try XCTUnwrap(object["passcode"] as? String)
}

private func quarkStoken(from episodeReference: String) throws -> String {
    let outerData = try XCTUnwrap(
        Data(base64Encoded: episodeReference, options: .ignoreUnknownCharacters)
    )
    let outer = try XCTUnwrap(
        JSONSerialization.jsonObject(with: outerData) as? [String: Any]
    )
    let playToken = try XCTUnwrap(outer["playToken"] as? String)
    let token = try XCTUnwrap(
        JSONSerialization.jsonObject(with: Data(playToken.utf8)) as? [String: Any]
    )
    return try XCTUnwrap(token["stoken"] as? String)
}

private actor PosterAdmissionProbe: HTTPClient {
    private let body: Data
    private let oldDelayNanoseconds: UInt64
    private var starts: [String: Int] = [:]
    private var cancellations: [String: Int] = [:]

    init(body: Data, oldDelayNanoseconds: UInt64) {
        self.body = body
        self.oldDelayNanoseconds = oldDelayNanoseconds
    }

    func send(_ request: HTTPRequest) async throws -> HTTPResponse {
        let key = request.url.lastPathComponent
        starts[key, default: 0] += 1
        if key.hasPrefix("old-") {
            do { try await Task.sleep(nanoseconds: oldDelayNanoseconds) }
            catch {
                cancellations[key, default: 0] += 1
                throw error
            }
        }
        return HTTPResponse(url: request.url, statusCode: 200,
            headers: ["Content-Type": "image/png"], body: body)
    }

    func oldStarts() -> Int { starts.filter { $0.key.hasPrefix("old-") }.values.reduce(0, +) }
    func newStarts() -> Int { starts["new-visible.png", default: 0] }
    func oldCancellations() -> Int { cancellations.values.reduce(0, +) }
}

private actor ImageRepositoryHTTPClientProbe: HTTPClient {
    private let body: Data?
    private let error: HTTPClientError?
    private let delayNanoseconds: UInt64
    private var failuresRemaining: Int
    private var count = 0

    init(body: Data, delayNanoseconds: UInt64 = 0) {
        self.body = body
        self.error = nil
        self.delayNanoseconds = delayNanoseconds
        failuresRemaining = 0
    }

    init(
        body: Data,
        failuresBeforeSuccess: Int,
        delayNanoseconds: UInt64 = 0
    ) {
        self.body = body
        self.error = nil
        self.delayNanoseconds = delayNanoseconds
        failuresRemaining = max(0, failuresBeforeSuccess)
    }

    init(error: HTTPClientError, delayNanoseconds: UInt64 = 0) {
        self.body = nil
        self.error = error
        self.delayNanoseconds = delayNanoseconds
        failuresRemaining = 0
    }

    func send(_ request: HTTPRequest) async throws -> HTTPResponse {
        count += 1
        if delayNanoseconds > 0 {
            try await Task.sleep(nanoseconds: delayNanoseconds)
        }
        if let error {
            throw error
        }
        if failuresRemaining > 0 {
            failuresRemaining -= 1
            throw HTTPClientError.statusCode(503)
        }
        return HTTPResponse(
            url: request.url,
            statusCode: 200,
            headers: ["Content-Type": "image/tiff"],
            body: body ?? Data()
        )
    }

    func requestCount() -> Int {
        count
    }
}

private actor ImageRefererFallbackHTTPClient: HTTPClient {
    private let imageData: Data
    private let initialStatus: Int
    private let fallbackStatus: Int?
    private var requests: [HTTPRequest] = []

    init(
        imageData: Data,
        initialStatus: Int,
        fallbackStatus: Int? = nil
    ) {
        self.imageData = imageData
        self.initialStatus = initialStatus
        self.fallbackStatus = fallbackStatus
    }

    func send(_ request: HTTPRequest) async throws -> HTTPResponse {
        requests.append(request)
        let hasReferer = request.headers["Referer"]?.isEmpty == false
        if !hasReferer {
            throw HTTPClientError.statusCode(initialStatus)
        }
        if let fallbackStatus {
            throw HTTPClientError.statusCode(fallbackStatus)
        }
        return HTTPResponse(
            url: request.url,
            statusCode: 200,
            headers: ["Content-Type": "image/tiff"],
            body: imageData
        )
    }

    func capturedRequests() -> [HTTPRequest] {
        requests
    }
}

private actor NodeProxyEndpointTransitionHTTPClient: HTTPClient {
    private let stalePort: Int
    private let imageData: Data
    private var ports: [Int] = []

    init(stalePort: Int, imageData: Data) {
        self.stalePort = stalePort
        self.imageData = imageData
    }

    func send(_ request: HTTPRequest) async throws -> HTTPResponse {
        let port = request.url.port ?? -1
        ports.append(port)
        if port == stalePort {
            try await Task.sleep(nanoseconds: 150_000_000)
            throw HTTPClientError.statusCode(503)
        }
        return HTTPResponse(
            url: request.url,
            statusCode: 200,
            headers: ["Content-Type": "image/tiff"],
            body: imageData
        )
    }

    func requestCount() -> Int {
        ports.count
    }

    func requestedPorts() -> [Int] {
        ports
    }
}

final class AndroidRuntimeModeCompatibilityTests: XCTestCase {
    func testNewUserMigratesToManagedAndPersistsAcrossRelaunch() throws {
        let fixture = try makeFixture()
        defer { fixture.cleanup() }
        let store = fixture.store

        let first = try store.loadOrMigrate(managedRuntimeUsable: false)
        let second = try store.loadOrMigrate(managedRuntimeUsable: false)

        XCTAssertEqual(first.mode, .managed)
        XCTAssertEqual(first.selectionSource, .newUserDefault)
        XCTAssertEqual(second, first)
    }

    func testUsableManagedRuntimeWinsOverHistoricalExternalPreference() throws {
        let fixture = try makeFixture(legacySDKRoot: "/legacy/sdk")
        defer { fixture.cleanup() }

        let record = try fixture.store.loadOrMigrate(
            managedRuntimeUsable: true
        )

