    private struct Fixture {
        let root: URL
        let support: URL
        let defaults: UserDefaults
        let suiteName: String
        let store: AndroidRuntimeModeStore

        func cleanup() {
            defaults.removePersistentDomain(forName: suiteName)
            try? FileManager.default.removeItem(at: root)
        }
    }

    private func makeFixture(legacySDKRoot: String? = nil) throws -> Fixture {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(
            "AndroidRuntimeMode-\(UUID().uuidString)",
            isDirectory: true
        )
        let support = root.appendingPathComponent("Application Support")
        try FileManager.default.createDirectory(
            at: support,
            withIntermediateDirectories: true
        )
        let suiteName = "AndroidRuntimeModeTests.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suiteName))
        defaults.removePersistentDomain(forName: suiteName)
        if let legacySDKRoot {
            defaults.set(
                legacySDKRoot,
                forKey: AndroidRuntimeModeStore.legacySDKRootDefaultsKey
            )
        }
        return Fixture(
            root: root,
            support: support,
            defaults: defaults,
            suiteName: suiteName,
            store: AndroidRuntimeModeStore(
                applicationSupportDirectory: support,
                defaults: defaults
            )
        )
    }

    private func makeValidator(
        fixture: Fixture,
        javaRuntime: AndroidJavaRuntime?
    ) -> ExternalAndroidRuntimeValidator {
        ExternalAndroidRuntimeValidator(
            applicationSupportDirectory: fixture.support,
            homeDirectory: fixture.root,
            environment: [:],
            architectureInspector: { _ in true },
            javaResolver: { javaRuntime }
        )
    }

    private func makeCoordinator(
        fixture: Fixture,
        validator: ExternalAndroidRuntimeValidator,
        managedRuntimeUsableAtMigration: Bool,
        managedUsability: Bool,
        probe: AndroidRuntimeRoutingProbe
    ) throws -> AndroidRuntimeModeCoordinator {
        try AndroidRuntimeModeCoordinator(
            store: fixture.store,
            layout: AndroidRuntimeLayout(
                applicationSupportDirectory: fixture.support
            ),
            catalog: try BundledRuntimeCatalog.load(),
            externalValidator: validator,
            managedRuntimeUsableAtMigration: managedRuntimeUsableAtMigration,
            managedUsability: { managedUsability },
            ensureManagedReady: {
                await probe.recordManagedAdmission()
            },
            cancelManagedAdmission: {
                await probe.recordManagedCancellation()
            },
            managedAVDAdmission: {},
            configureSession: { mode, root in
                await probe.recordConfiguration(mode: mode, sdkRoot: root)
            },
            sessionStatus: {
                await probe.sessionStatus
            }
        )
    }

    private func makeSDK(
        at root: URL,
        includeAVDManager: Bool
    ) throws {
        try makeExecutable(at: root.appendingPathComponent("platform-tools/adb"))
        try makeExecutable(at: root.appendingPathComponent("emulator/emulator"))
        if includeAVDManager {
            try makeExecutable(
                at: root.appendingPathComponent(
                    "cmdline-tools/latest/bin/avdmanager"
                )
            )
        }
        let source = root.appendingPathComponent("emulator/source.properties")
        try Data("Pkg.Revision=36.6.11\n".utf8).write(
            to: source,
            options: [.atomic]
        )
    }

    private func makeExecutable(at url: URL) throws {
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        XCTAssertTrue(FileManager.default.createFile(
            atPath: url.path,
            contents: Data("#!/bin/sh\nexit 0\n".utf8)
        ))
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o700],
            ofItemAtPath: url.path
        )
    }

    private func makeSystemImage(
        at sdk: URL,
        variant: String = "default"
    ) throws {
        let directory = sdk.appendingPathComponent(
            "system-images/android-35/\(variant)/arm64-v8a",
            isDirectory: true
        )
        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )
        let xml = """
        <?xml version="1.0" encoding="UTF-8"?>
        <sdk:sdk-repository xmlns:sdk="http://schemas.android.com/sdk/android/repo/repository2/01">
          <localPackage path="system-images;android-35;\(variant);arm64-v8a">
            <type-details>
              <api-level>35</api-level>
              <extension-level>0</extension-level>
              <tag><id>\(variant)</id><display>\(variant)</display></tag>
              <abi>arm64-v8a</abi>
            </type-details>
          </localPackage>
        </sdk:sdk-repository>
        """
        try Data(xml.utf8).write(
            to: directory.appendingPathComponent("package.xml"),
            options: [.atomic]
        )
    }

    private func makeAVD(
        in support: URL,
        variant: String = "default"
    ) throws {
        let layout = AndroidRuntimeLayout(
            applicationSupportDirectory: support
        )
        try FileManager.default.createDirectory(
            at: layout.avdDirectory,
            withIntermediateDirectories: true
        )
        let config = """
        abi.type=arm64-v8a
        image.sysdir.1=system-images/android-35/\(variant)/arm64-v8a/
        tag.id=\(variant)
        target=android-35
        hw.gpu.enabled=yes
        hw.gpu.mode=host
        """
        try Data(config.utf8).write(
            to: layout.avdDirectory.appendingPathComponent("config.ini"),
            options: [.atomic]
        )
    }
}

private actor AndroidRuntimeRoutingProbe {
    struct Configuration: Equatable, Sendable {
        let mode: AndroidRuntimeMode
        let sdkRoot: URL?
    }

    private(set) var managedAdmissionCount = 0
    private(set) var managedCancellationCount = 0
    private(set) var configurations: [Configuration] = []
    let sessionStatus: AndroidRuntimeStatus

    init(sessionStatus: AndroidRuntimeStatus = .stopped) {
        self.sessionStatus = sessionStatus
    }

    func recordManagedAdmission() {
        managedAdmissionCount += 1
    }

    func recordManagedCancellation() {
        managedCancellationCount += 1
    }

    func recordConfiguration(mode: AndroidRuntimeMode, sdkRoot: URL?) {
        configurations.append(Configuration(mode: mode, sdkRoot: sdkRoot))
    }
}

private actor AndroidRuntimeConfigurationBoundary {
    private var externalConfigurationStarted = false
    private var startWaiters: [CheckedContinuation<Void, Never>] = []
    private var releaseWaiters: [CheckedContinuation<Void, Never>] = []
    private var externalConfigurationReleased = false

    func configure(mode: AndroidRuntimeMode) async {
        guard mode == .external, !externalConfigurationReleased else { return }
        externalConfigurationStarted = true
        let waiters = startWaiters
        startWaiters.removeAll()
        waiters.forEach { $0.resume() }
        await withCheckedContinuation { continuation in
            releaseWaiters.append(continuation)
        }
    }

    func waitUntilExternalConfigurationStarts() async {
        if externalConfigurationStarted { return }
        await withCheckedContinuation { continuation in
            startWaiters.append(continuation)
        }
    }

    func releaseExternalConfiguration() {
        externalConfigurationReleased = true
        let waiters = releaseWaiters
        releaseWaiters.removeAll()
        waiters.forEach { $0.resume() }
    }
}

private final class AndroidRuntimeSynchronousCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var count = 0

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return count
    }

    func increment() {
        lock.lock()
        count += 1
        lock.unlock()
    }
}

final class AndroidMaintenanceAdmissionTests: XCTestCase {
    func testMaintenanceCancelsAndJoinsBridgeOperationsThenRejectsNewRequests() async throws {
        let admission = AndroidBridgeOperationAdmission()
        let started = expectation(description: "operation admitted")
        let operation = Task {
            try await admission.perform {
                started.fulfill()
                try await Task.sleep(nanoseconds: 30_000_000_000)
                return 1
            }
        }
        await fulfillment(of: [started], timeout: 2)
        try await admission.closeAndWait()
        do { _ = try await operation.value; XCTFail("cancelled operation completed") }
        catch is CancellationError {} catch { XCTFail("unexpected error") }
        do { _ = try await admission.perform { 2 }; XCTFail("admitted while closed") }
        catch { XCTAssertEqual(error as? RuntimeMaintenanceError, .busy) }
        await admission.reopen()
        let value = try await admission.perform { 3 }
        XCTAssertEqual(value, 3)
    }
}

extension AndroidRuntimeModeCompatibilityTests {
    func testMaintenanceFreezesModeAndDexAdmissionWithoutChangingSelection() async throws {
        let fixture = try makeFixture(legacySDKRoot: nil)
        defer { fixture.cleanup() }
        _ = try fixture.store.loadOrMigrate(managedRuntimeUsable: false)
        let original = try Data(contentsOf: fixture.store.recordURL)
        let probe = AndroidRuntimeRoutingProbe()
        let coordinator = try makeCoordinator(fixture: fixture,
            validator: makeValidator(fixture: fixture, javaRuntime: nil),
            managedRuntimeUsableAtMigration: false, managedUsability: false, probe: probe)
        let token = try await coordinator.beginMaintenance()
        do { try await coordinator.prepareRuntime(); XCTFail("Dex admitted") }
        catch { XCTAssertEqual(error as? RuntimeMaintenanceError, .busy) }
        do { _ = try await coordinator.useManagedRuntime(); XCTFail("mode changed") }
        catch { XCTAssertEqual(error as? RuntimeMaintenanceError, .busy) }
        XCTAssertEqual(original, try Data(contentsOf: fixture.store.recordURL))
        await coordinator.endMaintenance(token)
        _ = try await coordinator.useManagedRuntime()
        XCTAssertEqual(original, try Data(contentsOf: fixture.store.recordURL))
    }
}

@MainActor
final class LiveGuideGridTests: XCTestCase {
    private let start = Date(timeIntervalSince1970: 2_000_000_000)

    func testPartiallyClippedTopProgrammeKeepsItsOriginalTextOrigin() throws {
        let model = try fixture(rows: 48, programmesPerRow: 24)
        let view = LiveGuideGridView(frame: .init(x: 0, y: 0, width: 1100, height: 720))
        let window = NSWindow(contentRect: view.frame, styleMask: [.titled], backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false; window.contentView = view
        defer { window.close() }
        view.apply(model, now: start)
        view.layoutSubtreeIfNeeded()
        view.scroll(to: .init(x: 80, y: 5 * LiveGuideGridView.rowHeight + 51))
        view.displayIfNeeded()
        let frames = view.debugVisibleProgrammeFrames
        let partial = try XCTUnwrap(frames.first { $0.minY < 0 })
        XCTAssertLessThan(partial.minY + 8 + 20, 0,
            "The previous row title must stay above the clip, never be repositioned into the next row")
        XCTAssertLessThan(partial.maxY, LiveGuideGridView.rowHeight)
        let next = try XCTUnwrap(frames.first { $0.minY >= 0 })
        XCTAssertGreaterThanOrEqual(next.minY, partial.maxY)
        let output = URL(fileURLWithPath: "/private/tmp/OKVideoMac-UX109-Visuals", isDirectory: true)
        try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
        let bitmap = try XCTUnwrap(view.bitmapImageRepForCachingDisplay(in: view.bounds))
        view.cacheDisplay(in: view.bounds, to: bitmap)
        try XCTUnwrap(bitmap.representation(using: .png, properties: [:])).write(to: output.appendingPathComponent("guide-partial-top.png"))
    }

    func testNativeGuideUsesOneClipAndBoundedDrawingMemory() async throws {
        let initial = try fixture(rows: 48, programmesPerRow: 24)
        let model = try LiveGuideGridModel(windowStart: start,
            windowEnd: start.addingTimeInterval(24 * 3600), timeZone: .current, rows: initial.rows)
        let sampler = LiveGuideResourceSampler(); sampler.start()
        let view = LiveGuideGridView(frame: .init(x: 0, y: 0, width: 1100, height: 720))
        let window = NSWindow(contentRect: view.frame, styleMask: [.titled], backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false; window.contentView = view; window.makeKeyAndOrderFront(nil)
        defer { window.close() }
        view.apply(model, now: start)
        view.layoutSubtreeIfNeeded(); view.displayIfNeeded()
        let scrolls = BrowserKeyboardView.descendants(of: view).compactMap { $0 as? NSScrollView }
        XCTAssertEqual(scrolls.count, 1)
        let scroll = try XCTUnwrap(scrolls.first)
        let document = try XCTUnwrap(scroll.documentView)
        XCTAssertGreaterThan(document.frame.width, scroll.contentSize.width)
        for index in 0..<24 {
            scroll.contentView.scroll(to: .init(x: CGFloat(index % 8) * 300, y: CGFloat(index % 6) * 360))
            scroll.reflectScrolledClipView(scroll.contentView)
            view.displayIfNeeded()
            try await Task.sleep(nanoseconds: 20_000_000)
            XCTAssertEqual(view.scrollOffset, scroll.contentView.bounds.origin)
            XCTAssertLessThanOrEqual(view.debugMetrics.visibleProgrammeViews, 200)
            XCTAssertTrue(document.subviews.allSatisfy { $0.bounds.width <= scroll.contentSize.width + 1 && $0.bounds.height <= scroll.contentSize.height + 1 })
        }
        let measurement = sampler.stop()
        let growth = Int64(measurement.peak.footprint) - Int64(measurement.baseline.footprint)
        print("UX109 guide: footprint growth \(growth) bytes; document layer \(document.layer != nil); raster contents \(document.layer?.contents != nil)")
        XCTAssertLessThan(growth, 128 * 1024 * 1024, "A guide must not allocate a bitmap for the entire logical document")
    }

    func testFixtureGridVirtualizesBothAxesAndKeepsFixedRegionsStable() throws {
        let model = try fixture(rows: 48, programmesPerRow: 24)
        let view = LiveGuideGridView(frame: NSRect(x: 0, y: 0, width: 980, height: 620))
        let window = NSWindow(contentRect: view.frame, styleMask: [.borderless], backing: .buffered,
                              defer: false)
